import{_ as l,o as t,c as i,a6 as e}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"第九章：GPU","description":"从 Bit 到 AGI 专栏 · 硬件与算力 · 共 10 篇","frontmatter":{"title":"第九章：GPU","description":"从 Bit 到 AGI 专栏 · 硬件与算力 · 共 10 篇","source":"https://daiw.org/manual/bit-to-agi/09-gpu"},"headers":[],"relativePath":"manual/llm/bit-to-agi/09-gpu.md","filePath":"manual/llm/bit-to-agi/09-gpu.md"}'),r={name:"manual/llm/bit-to-agi/09-gpu.md"};function o(n,a,u,m,p,s){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="第九章-gpu" tabindex="-1">第九章：GPU <a class="header-anchor" href="#第九章-gpu" aria-label="Permalink to &quot;第九章：GPU&quot;">​</a></h1><blockquote><p>从 Bit 到 AGI 专栏 · 硬件与算力 · 共 10 篇</p></blockquote><p>训练一个 70B 参数的模型，需要把数百 GB 的权重塞进显存，再用每秒数千 TFLOPS 的算力做矩阵乘法——这一切发生在 GPU 上。本章从程序员视角拆解 NVIDIA GPU 的关键概念：CUDA 编程模型、HBM 带宽、NVLink 与 PCIe 互联、Warp 与 SM 执行单元、Tensor Core 算力，以及为什么显存容量决定你能跑多大的模型。</p><h2 id="本章目录" tabindex="-1">本章目录 <a class="header-anchor" href="#本章目录" aria-label="Permalink to &quot;本章目录&quot;">​</a></h2><ol><li><a href="/Front2Full/manual/llm/bit-to-agi/09-gpu/what-is-cuda">CUDA 是什么</a> — 用 C 写并行程序的平台</li><li><a href="/Front2Full/manual/llm/bit-to-agi/09-gpu/what-is-hbm">HBM 是什么</a> — 显存带宽为何以 TB/s 计</li><li><a href="/Front2Full/manual/llm/bit-to-agi/09-gpu/what-is-nvlink">NVLink 是什么</a> — GPU 之间的高速通道</li><li><a href="/Front2Full/manual/llm/bit-to-agi/09-gpu/what-is-pcie">PCIe 是什么</a> — GPU 与 CPU/主机之间的瓶颈</li><li><a href="/Front2Full/manual/llm/bit-to-agi/09-gpu/what-is-warp">Warp 是什么</a> — 32 线程同步执行的基本单位</li><li><a href="/Front2Full/manual/llm/bit-to-agi/09-gpu/what-is-sm">SM 是什么</a> — GPU 上的「多核处理器」</li><li><a href="/Front2Full/manual/llm/bit-to-agi/09-gpu/tensor-core">Tensor Core 与 TFLOPS</a> — 矩阵乘法的专用硬件</li><li><a href="/Front2Full/manual/llm/bit-to-agi/09-gpu/why-gpu-so-fast">为什么 GPU 这么快</a> — 并行度、带宽与专用电路</li><li><a href="/Front2Full/manual/llm/bit-to-agi/09-gpu/why-vram-matters">为什么显存这么重要</a> — 7B / 70B 模型要占多少 GB</li><li><a href="/Front2Full/manual/llm/bit-to-agi/09-gpu/chapter-summary">本章总结</a></li></ol><h2 id="阅读建议" tabindex="-1">阅读建议 <a class="header-anchor" href="#阅读建议" aria-label="Permalink to &quot;阅读建议&quot;">​</a></h2><p>建议按目录顺序阅读：先理解 CUDA 如何把「成千上万个线程」映射到硬件，再理解 HBM / NVLink / PCIe 三条数据通路，然后深入 Warp、SM、Tensor Core 的执行细节，最后用「为什么 GPU 这么快」和「为什么显存这么重要」把概念串起来。读完本章后，<a href="/Front2Full/manual/llm/bit-to-agi/08-inference">第八章推理</a> 里的 KV Cache、张量并行等话题会更容易理解——它们本质上都是在 GPU 硬件约束下做取舍。</p><p>从本章开始阅读 → <a href="/Front2Full/manual/llm/bit-to-agi/09-gpu/what-is-cuda">CUDA 是什么</a></p>',8)])])}const c=l(r,[["render",o]]);export{g as __pageData,c as default};
